#!/usr/bin/env python3
"""Careerflow platform enhancements. Run from the repo root (the folder that holds backend/ and frontend/).
Safe to run twice: files already applied are skipped."""
import os, sys, zlib, base64
sys.stdout.reconfigure(errors='replace')
NEW = {"frontend/src/components/enh/PageReader.tsx": ""}
MOD = {"frontend/src/components/enh/ReviewSidePanel.tsx": [["import { xtriumApi } from '@/api/client'\nimport { SopViewer } from '@/components/SopViewer'\nimport { Blank, Chip, Skeletons, Tabs } from '@/components/enh/kit'\nimport { Button } from '@/components/ui'\n\ntype Tab = 'sop' | 'text' | 'web' | 'page'\n\nconst present = (v: unknown) => !(v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0))\n", "import { xtriumApi } from '@/api/client'\nimport { SopViewer } from '@/components/SopViewer'\nimport { Blank, Chip, Skeletons, Tabs } from '@/components/enh/kit'\nimport { Button } from '@/components/ui'\nimport { PageReader } from '@/components/enh/PageReader'\n\ntype Tab = 'sop' | 'text' | 'web' | 'page'\n\nconst present = (v: unknown) => !(v === null || v === undefined || v === '' || (Array.isArray(v) && v.length === 0))\n"], ["          </div>\n        ) : <Blank title=\"No website to show\" text=\"This record and source have no web address.\" />)}\n        {tab === 'page' && (pageText ? (\n          <div>\n            <p className=\"text-xs text-gray-500 mt-0 mb-3\">The page as Nimble read it. {activeField ? <>Matches for <b>{activeField}</b> are highlighted.</> : 'Click a field to highlight its value here.'}</p>\n            <Highlighted text={pageText} needle={activeValue} />\n          </div>\n        ) : (\n          <Blank title=\"Read the page here\" text={nimbleReady ? 'Nimble fetches the source website and shows its text here, with the value of the field you are on highlighted.' : 'Add NIMBLE_API_KEY in the server settings to turn this on.'}\n            action={nimbleReady ? <Button disabled={pageBusy} onClick={onFetchPage}>{pageBusy ? 'Reading the site…' : 'Read the page'}</Button> : undefined} />\n", "          </div>\n        ) : <Blank title=\"No website to show\" text=\"This record and source have no web address.\" />)}\n        {tab === 'page' && (pageText ? (\n          <div>\n            <p className=\"text-xs text-gray-500 mt-0 mb-1\">The page as Nimble read it. {activeField ? <>Matches for <b>{activeField}</b> are highlighted.</> : 'Click a field to highlight its value here.'}</p>\n            <PageReader text={pageText} needle={activeValue} field={activeField} />\n          </div>\n        ) : (\n          <Blank title=\"Read the page here\" text={nimbleReady ? 'Nimble fetches the source website and shows its text here, with the value of the field you are on highlighted.' : 'Add NIMBLE_API_KEY in the server settings to turn this on.'}\n            action={nimbleReady ? <Button disabled={pageBusy} onClick={onFetchPage}>{pageBusy ? 'Reading the site…' : 'Read the page'}</Button> : undefined} />\n"]]}
root = os.getcwd()
if not (os.path.isdir(os.path.join(root, 'backend')) and os.path.isdir(os.path.join(root, 'frontend'))):
    sys.exit('Run this from the repo root (the folder containing backend and frontend).')
def rd(p): return open(p, encoding='utf-8', newline='').read()
done = skipped = 0; bad = []
for rel, hunks in MOD.items():
    p = os.path.join(root, rel)
    if not os.path.exists(p): bad.append(rel + ' (missing)'); continue
    raw = rd(p); crlf = '\r\n' in raw; t = raw.replace('\r\n', '\n'); changed = False
    for old, new in hunks:
        if new in t: continue
        elif t.count(old) == 1: t = t.replace(old, new); changed = True
        else: bad.append(rel + ' (a section does not match; file differs from expected version)'); break
    else:
        if changed:
            open(p, 'w', encoding='utf-8', newline='').write(t.replace('\n', '\r\n') if crlf else t); done += 1; print('updated ', rel)
        else: skipped += 1
for rel, blob in NEW.items():
    p = os.path.join(root, rel); data = zlib.decompress(base64.b64decode(blob))
    if os.path.exists(p) and open(p, 'rb').read() == data: skipped += 1; continue
    os.makedirs(os.path.dirname(p), exist_ok=True); open(p, 'wb').write(data); done += 1; print('wrote   ', rel)
print(f'\n{done} changed, {skipped} already applied.')
if bad:
    print('\nPROBLEMS:'); [print(' -', b) for b in bad]; sys.exit(1)
